// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;

    // The Owner of C is the deployer (this test contract). It must be able to
    // accept ETH via transfer() so the reference's full-balance payout succeeds.
    receive() external payable {}

    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 deposit, uint256 value, address actor) public {
        // wide admissible domain: any funder, any deposit, any call value
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        deposit = bound(deposit, 0, type(uint128).max);
        value = bound(value, 0, type(uint128).max);

        // fund the contract: any actor sends `deposit` straight into c's receive()
        vm.deal(actor, deposit);
        vm.prank(actor);
        (bool funded,) = address(c).call{value: deposit}("");
        assertTrue(funded);

        // Owner calls the payable withdraw() with arbitrary msg.value = `value`
        vm.deal(address(this), value);
        (bool ok, ) = address(c).call{value: value}(abi.encodeWithSelector(c.withdraw.selector));

        // GENERAL RULE: whenever withdraw() succeeds (for ANY call value v and ANY
        // held balance d), the Owner receives d + v and the contract is left EMPTY:
        // address(c).balance == 0. The mutant sends only msg.value, so with
        // value == 0 and deposit > 0 it succeeds yet leaves `deposit` locked in c.
        assertTrue(!ok || address(c).balance == 0);
    }
}
